   "code": "// Percentiles from raw latency samples (ms), and the fan-out effect\nfunction percentile(samples, p) {\n  const s = [...samples].sort((a, b) => a - b);\n  const i = Math.min(s.length - 1, Math.ceil((p / 100) * s.length) - 1);\n  return s[i];\n}\n\nconst latencies = [12, 15, 14, 13, 250, 16, 12, 18, 14, 900, 13, 15];\nconsole.log('p50', percentile(latencies, 50)); // 14\nconsole.log('p99', percentile(latencies, 99)); // 900\nconst avg = latencies.reduce((a, b) => a + b) / latencies.length;\nconsole.log('avg', avg.toFixed(1)); // 107.7: describes nobody\n\n// Chance that a page making n calls meets at least one slow call\nconst slowAtLeastOnce = (n, pSlow = 0.01) => 1 - Math.pow(1 - pSlow, n);\nconsole.log(slowAtLeastOnce(1));   // 0.01\nconsole.log(slowAtLeastOnce(100)); // about 0.63",
