   "code": "// Retries done right: limited, exponential backoff, full jitter, and a timeout per attempt\nasync function withRetry(fn, { attempts = 3, baseMs = 100, timeoutMs = 2000 } = {}) {\n  for (let i = 0; ; i++) {\n    try {\n      return await Promise.race([\n        fn(),\n        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), timeoutMs)),\n      ]);\n    } catch (err) {\n      if (i >= attempts - 1) throw err;          // give up: let the caller degrade\n      const cap = baseMs * 2 ** i;                // 100, 200, 400 ...\n      await new Promise(r => setTimeout(r, Math.random() * cap)); // jitter\n    }\n  }\n}\n\n// usage\n// const user = await withRetry(() => fetch('/api/user/42').then(r => r.json()));",
