   "code": "// Load shedding: refuse work you cannot finish instead of queueing forever (Express)\nconst LIMIT = 200; // from Little's Law plus headroom\nlet inFlightNow = 0;\n\napp.use((req, res, next) => {\n  if (inFlightNow >= LIMIT) {\n    res.set('Retry-After', '1');\n    return res.status(503).send('busy, try again');  // fast failure keeps the server healthy\n  }\n  inFlightNow++;\n  res.on('finish', () => inFlightNow--);\n  res.on('close', () => { if (!res.writableEnded) inFlightNow--; });\n  next();\n});",
